snapshot(): deep copy of the effective settings.
restore(snap): replace effective settings with the snapshot.
"""

import copy


def _get_path(cfg, key, default=None):
    cur = cfg
    for part in key.split("."):
        if not isinstance(cur, dict) or part not in cur:
            return default
        cur = cur[part]
    return cur


def get(key, default=None):
    return _get_path(_EFFECTIVE, key, default)


def set(key, value):
    parts = key.split(".")
    cur = _EFFECTIVE
    for part in parts[:-1]:
        if part not in cur or not isinstance(cur[part], dict):
            cur[part] = {}
        cur = cur[part]
    cur[parts[-1]] = value


def load(file_cfg, env):
    global _EFFECTIVE
    merged = merge(_DEFAULTS, file_cfg)
    merged = merge(merged, env)
    _EFFECTIVE = merged
    return merged


def validate(cfg):
    limits = _get_path(cfg, "limits", {})
    if not isinstance(limits, dict):
        return True

    def valid(values):
        for value in values.values():
            if isinstance(value, dict):
                if not valid(value):
                    return False
            else:
