            out[k] = merge(out[k], v)
        else:
            out[k] = copy.deepcopy(v)
    return out


def snapshot():
    return copy.deepcopy(_EFFECTIVE)


def restore(snap):
    global _EFFECTIVE
    _EFFECTIVE = copy.deepcopy(snap)


